-- GhostSlot Campus Twin: rooms, sensor readings, water meters and the
-- analysis functions behind the Twin tab (utilisation, energy waste,
-- water anomalies, live room state).
--
-- DATA HONESTY: CU has no live meter feed connected yet. Readings are
-- generated by gs_twin_generate() with realistic daily patterns and
-- injected waste/leak episodes, and every row is tagged source='simulated'.
-- Real ESP32 / meter data goes in the same tables with source='sensor'.
--
-- SECURITY: RLS on with no policies, and no grants or function EXECUTE for
-- anon/authenticated. Only the GhostSlot server (service-role key) can read
-- or write any of this through the Supabase API.

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------
create table if not exists public.gs_twin_rooms (
  id         text primary key check (id ~ '^[A-Za-z0-9-]{2,40}$'),
  name       text not null,
  block      text not null,
  kind       text not null check (kind in ('classroom', 'lab', 'lecture_hall', 'pod')),
  capacity   int  not null check (capacity > 0),
  rated_kw   numeric(6,2) not null check (rated_kw > 0),   -- lights + fans + AC when fully on
  base_util  numeric(4,2) not null check (base_util between 0 and 1)
);

create table if not exists public.gs_twin_readings (
  room_id    text not null references public.gs_twin_rooms(id) on delete cascade,
  ts         timestamptz not null,                          -- start of a 15-minute interval
  occupants  int not null check (occupants >= 0),
  power_kw   numeric(7,3) not null check (power_kw >= 0),   -- average draw over the interval
  source     text not null default 'simulated' check (source in ('simulated', 'sensor')),
  primary key (room_id, ts)
);
create index if not exists gs_twin_readings_ts_idx on public.gs_twin_readings(ts);

create table if not exists public.gs_twin_buildings (
  id         text primary key check (id ~ '^[A-Za-z0-9-]{1,40}$'),
  name       text not null,
  base_l15   numeric(8,1) not null check (base_l15 > 0)     -- typical litres per 15 min at peak
);

create table if not exists public.gs_twin_water (
  building_id text not null references public.gs_twin_buildings(id) on delete cascade,
  ts          timestamptz not null,
  litres      numeric(9,1) not null check (litres >= 0),
  source      text not null default 'simulated' check (source in ('simulated', 'sensor')),
  primary key (building_id, ts)
);
create index if not exists gs_twin_water_ts_idx on public.gs_twin_water(ts);

-- Facilities staff marking an alert as handled. Alerts themselves are
-- computed from the readings; only the human decision is stored.
create table if not exists public.gs_twin_alert_acks (
  alert_key  text primary key check (char_length(alert_key) between 3 and 120),
  status     text not null check (status in ('acknowledged', 'resolved')),
  user_id    uuid references public.gs_users(id) on delete set null,
  at         timestamptz not null default now()
);

alter table public.gs_twin_rooms      enable row level security;
alter table public.gs_twin_readings   enable row level security;
alter table public.gs_twin_buildings  enable row level security;
alter table public.gs_twin_water      enable row level security;
alter table public.gs_twin_alert_acks enable row level security;
alter table public.gs_twin_rooms      force row level security;
alter table public.gs_twin_readings   force row level security;
alter table public.gs_twin_buildings  force row level security;
alter table public.gs_twin_water      force row level security;
alter table public.gs_twin_alert_acks force row level security;
revoke all on public.gs_twin_rooms, public.gs_twin_readings, public.gs_twin_buildings,
              public.gs_twin_water, public.gs_twin_alert_acks from anon, authenticated;

