-- ---------------------------------------------------------------------------
-- Deterministic pseudo-random in [0,1) from a text seed, so regenerating a
-- time range always gives the same numbers.
-- ---------------------------------------------------------------------------
create or replace function public.gs_rand(seed text) returns double precision
language sql immutable as $$
  select ((('x' || lpad(substr(md5(seed), 1, 8), 16, '0'))::bit(64)::bigint) % 1000000) / 1000000.0
$$;

-- ---------------------------------------------------------------------------
-- Simulator: fills 15-minute readings for every room and building between
-- two timestamps. Existing rows are never overwritten.
-- ---------------------------------------------------------------------------
create or replace function public.gs_twin_generate(p_from timestamptz, p_to timestamptz)
returns integer language plpgsql as $$
declare n1 int; n2 int;
begin
  if p_to - p_from > interval '31 days' then raise exception 'range too large'; end if;

  insert into public.gs_twin_readings (room_id, ts, occupants, power_kw, source)
  select r.id, t,
         case when occ then greatest(1, round(r.capacity * (0.40 + 0.55 * public.gs_rand(r.id || t::text || 'n'))))::int else 0 end,
         round((case
                  when occ   then r.rated_kw * (0.65 + 0.30 * public.gs_rand(r.id || t::text || 'p'))
                  when waste then r.rated_kw * (0.62 + 0.15 * public.gs_rand(r.id || t::text || 'w'))
                  else            r.rated_kw * 0.03
                end)::numeric, 3),
         'simulated'
  from public.gs_twin_rooms r
  cross join generate_series(date_bin('15 minutes', p_from, timestamptz '2000-01-01'), p_to, interval '15 minutes') as t
  cross join lateral (
    select extract(hour   from t at time zone 'Asia/Kolkata')::int as h,
           extract(isodow from t at time zone 'Asia/Kolkata')::int as dow,
           (t at time zone 'Asia/Kolkata')::date as d
  ) l
  cross join lateral (
    select case
             when l.dow = 7 then 0
             when l.dow = 6 then case when l.h between 10 and 12 then 0.15 * r.base_util else 0 end
             when l.h between 9 and 12 or l.h between 14 and 16 then least(0.95, r.base_util * 1.15)
             when l.h = 13 then r.base_util * 0.5
             when l.h in (8, 17) then r.base_util * 0.25
             else 0
           end as p_occ
  ) p
  cross join lateral (
    -- a class fills a whole hour, so the draw is per room per hour
    select public.gs_rand(r.id || date_trunc('hour', t)::text) < p.p_occ as occ
  ) o
  cross join lateral (
    select not o.occ and (
             -- lights/AC left on for a 3-hour block after people leave
             (l.h between 8 and 21 and public.gs_rand(r.id || l.d::text || 'w' || (l.h / 3)::text) < 0.10)
             -- forgotten overnight
          or ((l.h >= 18 or l.h < 7) and public.gs_rand(r.id || l.d::text || 'night') < 0.06)
           ) as waste
  ) w
  on conflict do nothing;
  get diagnostics n1 = row_count;

  insert into public.gs_twin_water (building_id, ts, litres, source)
  select b.id, t,
         round((b.base_l15 * prof * (0.85 + 0.30 * public.gs_rand(b.id || t::text))
                + case when leak then b.base_l15 * (0.55 + 0.25 * public.gs_rand(b.id || t::text || 'l')) else 0 end)::numeric, 1),
         'simulated'
  from public.gs_twin_buildings b
  cross join generate_series(date_bin('15 minutes', p_from, timestamptz '2000-01-01'), p_to, interval '15 minutes') as t
  cross join lateral (
    select extract(hour   from t at time zone 'Asia/Kolkata')::int as h,
           extract(isodow from t at time zone 'Asia/Kolkata')::int as dow,
           (t at time zone 'Asia/Kolkata')::date as d
  ) l
  cross join lateral (
    select case
             when l.dow >= 6 then case when l.h between 8 and 20 then 0.30 else 0.05 end
             when l.h between 8 and 17 then 1.0
             when l.h between 6 and 7 or l.h between 18 and 21 then 0.40
             else 0.06
           end as prof,
           -- a leaking tap / running cistern, 1 to 5 AM on some nights
           (l.h between 1 and 4 and public.gs_rand(b.id || l.d::text || 'leak') < 0.08) as leak
  ) x
  on conflict do nothing;
  get diagnostics n2 = row_count;

  return n1 + n2;
end $$;

-- ---------------------------------------------------------------------------
-- Analysis
-- ---------------------------------------------------------------------------

-- Weekday utilisation (% of 15-min intervals occupied) by room and hour.
create or replace function public.gs_twin_heatmap(p_days int default 7)
returns table (room_id text, hour int, util_pct numeric)
language sql stable as $$
  select r.room_id,
         extract(hour from r.ts at time zone 'Asia/Kolkata')::int as hour,
         round(100.0 * avg((r.occupants > 0)::int), 1) as util_pct
  from public.gs_twin_readings r
  where r.ts >= now() - make_interval(days => greatest(1, least(p_days, 31)))
    and extract(isodow from r.ts at time zone 'Asia/Kolkata') between 1 and 5
    and extract(hour from r.ts at time zone 'Asia/Kolkata') between 8 and 19
  group by 1, 2
$$;

-- Energy per room: total, and wasted (nobody inside but drawing > 25% of
-- the room's rated load). Each reading covers 0.25 h.
create or replace function public.gs_twin_energy(p_days int default 7)
returns table (room_id text, total_kwh numeric, wasted_kwh numeric, waste_hours numeric, occupied_util_pct numeric)
language sql stable as $$
  select r.room_id,
         round(sum(r.power_kw * 0.25), 2),
         round(sum(case when r.occupants = 0 and r.power_kw > 0.25 * m.rated_kw then r.power_kw * 0.25 else 0 end), 2),
         round(sum(case when r.occupants = 0 and r.power_kw > 0.25 * m.rated_kw then 0.25 else 0 end), 2),
         round(100.0 * avg(case when extract(isodow from r.ts at time zone 'Asia/Kolkata') between 1 and 5
                                 and extract(hour from r.ts at time zone 'Asia/Kolkata') between 9 and 16
                                then (r.occupants > 0)::int end), 1)
  from public.gs_twin_readings r
  join public.gs_twin_rooms m on m.id = r.room_id
  where r.ts >= now() - make_interval(days => greatest(1, least(p_days, 31)))
  group by r.room_id
$$;

-- Daily campus energy: total vs wasted.
create or replace function public.gs_twin_energy_daily(p_days int default 14)
returns table (day date, total_kwh numeric, wasted_kwh numeric)
language sql stable as $$
  select (r.ts at time zone 'Asia/Kolkata')::date,
         round(sum(r.power_kw * 0.25), 1),
         round(sum(case when r.occupants = 0 and r.power_kw > 0.25 * m.rated_kw then r.power_kw * 0.25 else 0 end), 1)
  from public.gs_twin_readings r
  join public.gs_twin_rooms m on m.id = r.room_id
  where r.ts >= now() - make_interval(days => greatest(1, least(p_days, 31)))
  group by 1 order by 1
$$;

-- Water anomalies: robust z-score of each reading against the median and
-- MAD for the same building, hour of day and day type (weekday/weekend)
-- over the window. Returns readings with z above p_z.
create or replace function public.gs_twin_water_anomalies(p_days int default 7, p_z numeric default 6)
returns table (building_id text, ts timestamptz, litres numeric, baseline numeric, z numeric)
language sql stable as $$
  with w as (
    select x.*, extract(hour from x.ts at time zone 'Asia/Kolkata')::int as h,
           (extract(isodow from x.ts at time zone 'Asia/Kolkata') >= 6) as wkend
    from public.gs_twin_water x
    where x.ts >= now() - make_interval(days => greatest(1, least(p_days, 31)))
  ), med as (
    select building_id, h, wkend, percentile_cont(0.5) within group (order by litres) as m
    from w group by 1, 2, 3
  ), mad as (
    select w.building_id, w.h, w.wkend, med.m,
           percentile_cont(0.5) within group (order by abs(w.litres - med.m)) as mad
    from w join med using (building_id, h, wkend)
    group by 1, 2, 3, 4
  )
  select w.building_id, w.ts, w.litres, round(mad.m::numeric, 1),
         round(((w.litres - mad.m) / greatest(1.4826 * mad.mad, 5))::numeric, 1)
  from w join mad using (building_id, h, wkend)
  where (w.litres - mad.m) / greatest(1.4826 * mad.mad, 5) > p_z
  order by w.ts desc
$$;

-- Latest reading per room, with a state for the twin map.
create or replace function public.gs_twin_now()
returns table (room_id text, ts timestamptz, occupants int, power_kw numeric, state text)
language sql stable as $$
  select distinct on (r.room_id) r.room_id, r.ts, r.occupants, r.power_kw,
         case when r.occupants > 0 then 'occupied'
              when r.power_kw > 0.25 * m.rated_kw then 'wasting'
              else 'free' end
  from public.gs_twin_readings r
  join public.gs_twin_rooms m on m.id = r.room_id
  where r.ts <= now() and r.ts > now() - interval '2 hours'
  order by r.room_id, r.ts desc
$$;

-- None of these are callable through the public API.
revoke execute on function public.gs_rand(text)                           from public, anon, authenticated;
revoke execute on function public.gs_twin_generate(timestamptz, timestamptz) from public, anon, authenticated;
revoke execute on function public.gs_twin_heatmap(int)                    from public, anon, authenticated;
revoke execute on function public.gs_twin_energy(int)                     from public, anon, authenticated;
revoke execute on function public.gs_twin_energy_daily(int)               from public, anon, authenticated;
revoke execute on function public.gs_twin_water_anomalies(int, numeric)   from public, anon, authenticated;
revoke execute on function public.gs_twin_now()                           from public, anon, authenticated;
grant  execute on function public.gs_rand(text), public.gs_twin_generate(timestamptz, timestamptz),
                           public.gs_twin_heatmap(int), public.gs_twin_energy(int), public.gs_twin_energy_daily(int),
                           public.gs_twin_water_anomalies(int, numeric), public.gs_twin_now() to service_role;

-- Seed the last 14 days so the dashboards have history from the start.
select public.gs_twin_generate(now() - interval '14 days', now());
